import torch
import torch.distributed as dist
import torch.nn.functional as F


def _world_size():
    if dist.is_available() and dist.is_initialized():
        return dist.get_world_size()
    return 1


def _rank():
    if dist.is_available() and dist.is_initialized():
        return dist.get_rank()
    return 0


def _all_reduce(x):
    if _world_size() == 1:
        return x
    x = x.contiguous()
    dist.all_reduce(x, op=dist.ReduceOp.SUM)
    return x


def _all_gather_last_dim(x):
    ws = _world_size()
    if ws == 1:
        return x
    x = x.contiguous()
    parts = [torch.empty_like(x) for _ in range(ws)]
    dist.all_gather(parts, x)
    return torch.cat(parts, dim=-1).contiguous()


def _split_last_dim(x):
    ws = _world_size()
    if ws == 1:
        return x
    return torch.chunk(x, ws, dim=-1)[_rank()].contiguous()


class _CopyToParallelRegion(torch.autograd.Function):
    """Identity in forward, all-reduce of gradient in backward."""

    @staticmethod
    def forward(ctx, x):
        return x

    @staticmethod
    def backward(ctx, grad):
        return _all_reduce(grad.clone())


class _ReduceFromParallelRegion(torch.autograd.Function):
    """All-reduce in forward, identity in backward."""

    @staticmethod
    def forward(ctx, x):
        return _all_reduce(x.clone())

    @staticmethod
    def backward(ctx, grad):
        return grad


class _GatherFromParallelRegion(torch.autograd.Function):
    """All-gather along last dim in forward, split in backward."""

    @staticmethod
    def forward(ctx, x):
        return _all_gather_last_dim(x)

    @staticmethod
    def backward(ctx, grad):
        return _split_last_dim(grad)


class _ScatterToParallelRegion(torch.autograd.Function):
    """Split along last dim in forward, all-gather in backward."""

    @staticmethod
    def forward(ctx, x):
        return _split_last_dim(x)

    @staticmethod
    def backward(ctx, grad):
        return _all_gather_last_dim(grad)


class ColumnParallelLinear(torch.nn.Module):
    """Y = X A^T + b, with A split along the output dimension across ranks.

    The weight follows torch.nn.Linear layout: (out_features, in_features).
    Each rank holds rows [rank*out/ws : (rank+1)*out/ws] of the master weight
    (i.e. columns of A^T). Output is all-gathered along the last dimension.
    """

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        ws = _world_size()
        rank = _rank()
        assert out_features % ws == 0, "out_features must be divisible by world_size"
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = ws
        self.rank = rank
        self.output_size_per_partition = out_features // ws

        master_weight = master_weight.detach()
        assert tuple(master_weight.shape) == (out_features, in_features)
        start = rank * self.output_size_per_partition
        end = start + self.output_size_per_partition
        self.weight = torch.nn.Parameter(master_weight[start:end, :].clone().contiguous())

        if bias:
            self.bias = torch.nn.Parameter(
                torch.zeros(self.output_size_per_partition,
                            dtype=master_weight.dtype, device=master_weight.device)
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        x = _CopyToParallelRegion.apply(x)
        out = F.linear(x, self.weight, self.bias)
        return _GatherFromParallelRegion.apply(out)


class RowParallelLinear(torch.nn.Module):
    """Y = X A^T + b, with A split along the input dimension across ranks.

    The weight follows torch.nn.Linear layout: (out_features, in_features).
    Each rank holds columns [rank*in/ws : (rank+1)*in/ws] of the master weight
    (i.e. rows of A^T). Partial outputs are all-reduced; bias is full on each
    rank and added after the reduction.

    Input may be either the full input (last dim == in_features), in which case
    it is split across ranks, or an already-partitioned input
    (last dim == in_features // world_size).
    """

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        ws = _world_size()
        rank = _rank()
        assert in_features % ws == 0, "in_features must be divisible by world_size"
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = ws
        self.rank = rank
        self.input_size_per_partition = in_features // ws

        master_weight = master_weight.detach()
        assert tuple(master_weight.shape) == (out_features, in_features)
        start = rank * self.input_size_per_partition
        end = start + self.input_size_per_partition
        self.weight = torch.nn.Parameter(master_weight[:, start:end].clone().contiguous())

        if bias:
            self.bias = torch.nn.Parameter(
                torch.zeros(out_features, dtype=master_weight.dtype, device=master_weight.device)
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        if self.world_size > 1 and x.shape[-1] == self.in_features:
            x = _ScatterToParallelRegion.apply(x)
        partial = F.linear(x, self.weight)
        out = _ReduceFromParallelRegion.apply(partial)
        if self.bias is not None:
            out = out + self.bias
        return out
